"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[2890],{32908(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>p,frontMatter:()=>i,metadata:()=>h,toc:()=>d});var o=n(74848),a=n(28453);const s=n.p+"assets/images/apprentice-gone-poster-1dc3eaabf444ff0a974d61dcdf290bc4.webp",i={title:"The Product Survives, the Apprentices Don't: Why the Labour AI Saves Isn't Flowing Back to People",date:new Date("2026-11-23T00:00:00.000Z"),author:"@Mythogen Engine",lang:"en",section:"sober-record",topic:"apprentice-gone",category:"\u6559\u80b2\u8207\u52de\u52d5",article_tags:{zh:["AI \u8f49\u578b","\u52de\u52d5\u7d50\u69cb","\u5c31\u696d\u6536\u7e2e","\u52de\u5de5\u4efd\u984d","\u8cc7\u672c\u908f\u8f2f"],en:["AI transformation","labor-structure","job-market-contraction","labour-share","capital-logic"]},keywords:["AI displacement","apprenticeship","junior engineers","legacy code","labour costs","share buybacks","capital expenditure","tacit knowledge","entry-level jobs"],summary:"AI does not need to replace an entire product for people to disappear. When one senior engineer with AI handles a team's workload, junior and apprentice roles quietly stop opening. Capital markets reward capitalised assets and buybacks over slow-payback human training, cutting off the entry point that builds the next generation of senior engineers.",status:"published",reading_time:8,sidebar_label:"The Product Survives, the Apprentices Don't: Why the Labour AI Saves Isn't Flowing Back to People",sidebar_position:20261123,description:"AI does not need to replace an entire product for people to disappear. When one senior engineer with AI handles a team's workload, junior and apprentice roles quietly stop opening. Capital markets reward capitalised assets and buybacks over slow-payback human training, cutting off the entry point that builds the next generation of senior engineers.",slug:"/notes/apprentice-gone"},r=void 0,h={id:"notes/2026Q4/apprentice-gone",title:"The Product Survives, the Apprentices Don't: Why the Labour AI Saves Isn't Flowing Back to People",description:"AI does not need to replace an entire product for people to disappear. When one senior engineer with AI handles a team's workload, junior and apprentice roles quietly stop opening. Capital markets reward capitalised assets and buybacks over slow-payback human training, cutting off the entry point that builds the next generation of senior engineers.",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/notes/2026Q4/apprentice-gone.mdx",sourceDirName:"notes/2026Q4",slug:"/notes/apprentice-gone",permalink:"/en/docs/notes/apprentice-gone",draft:!1,unlisted:!1,tags:[],version:"current",sidebarPosition:20261123,frontMatter:{title:"The Product Survives, the Apprentices Don't: Why the Labour AI Saves Isn't Flowing Back to People",date:"2026-11-23T00:00:00.000Z",author:"@Mythogen Engine",lang:"en",section:"sober-record",topic:"apprentice-gone",category:"\u6559\u80b2\u8207\u52de\u52d5",article_tags:{zh:["AI \u8f49\u578b","\u52de\u52d5\u7d50\u69cb","\u5c31\u696d\u6536\u7e2e","\u52de\u5de5\u4efd\u984d","\u8cc7\u672c\u908f\u8f2f"],en:["AI transformation","labor-structure","job-market-contraction","labour-share","capital-logic"]},keywords:["AI displacement","apprenticeship","junior engineers","legacy code","labour costs","share buybacks","capital expenditure","tacit knowledge","entry-level jobs"],summary:"AI does not need to replace an entire product for people to disappear. When one senior engineer with AI handles a team's workload, junior and apprentice roles quietly stop opening. Capital markets reward capitalised assets and buybacks over slow-payback human training, cutting off the entry point that builds the next generation of senior engineers.",status:"published",reading_time:8,sidebar_label:"The Product Survives, the Apprentices Don't: Why the Labour AI Saves Isn't Flowing Back to People",sidebar_position:20261123,description:"AI does not need to replace an entire product for people to disappear. When one senior engineer with AI handles a team's workload, junior and apprentice roles quietly stop opening. Capital markets reward capitalised assets and buybacks over slow-payback human training, cutting off the entry point that builds the next generation of senior engineers.",slug:"/notes/apprentice-gone"},sidebar:"lucidRecord",previous:{title:"The Machine Is in Taiwan, the Person in Hong Kong, the Company in Singapore: Rules Name the Person, Enforcement Sees Only Machines and Paperwork",permalink:"/en/docs/notes/machine-taiwan-person-hong-kong"},next:{title:"How a Day-in-the-Life Video Became a Reason for Layoffs: People Without Capital Punishing People Without Capital",permalink:"/en/docs/notes/day-in-the-life-layoffs"}},l={},d=[{value:"One prompt can&#39;t build a product. Three people can.",id:"one-prompt-cant-build-a-product-three-people-can",level:2},{value:"The old noodle house on the second floor: the machines came, the apprentices left",id:"the-old-noodle-house-on-the-second-floor-the-machines-came-the-apprentices-left",level:2},{value:"Back in software terms: what disappears is the entry point",id:"back-in-software-terms-what-disappears-is-the-entry-point",level:2},{value:"Why money flows to machines, not people",id:"why-money-flows-to-machines-not-people",level:2},{value:"The efficiency law I used to believe, and where it breaks",id:"the-efficiency-law-i-used-to-believe-and-where-it-breaks",level:2},{value:"Investing in the machines&#39; future, not people&#39;s",id:"investing-in-the-machines-future-not-peoples",level:2}];function c(e){const t={a:"a",h2:"h2",img:"img",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.h2,{id:"one-prompt-cant-build-a-product-three-people-can",children:"One prompt can't build a product. Three people can."}),"\n",(0,o.jsx)("video",{src:"/video/apprentice-gone.mp4",poster:s,controls:!0,muted:!0,playsInline:!0,preload:"metadata",width:"100%"}),"\n",(0,o.jsx)(t.p,{children:"I recently came across a very typical argument under a post in a tech community. The post said: if anyone tells you your product can be replaced by a single prompt, don't believe it. All you lose is the money of the tiny minority who would build it themselves anyway. The engineers in the comments agreed. CI/CD, code signing, self-hosted runners: any one of these is enough to wear you down. What product can a single prompt finish?"}),"\n",(0,o.jsx)(t.p,{children:"They're right. Someone who can't code won't build a large, complete product that can be maintained for years."}),"\n",(0,o.jsxs)(t.p,{children:["But both sides of this argument are standing too far out. One side says AI will replace everything; the other says AI can't replace anything. What is actually happening sits in the middle, and few people want to say it: ",(0,o.jsx)(t.strong,{children:"the product doesn't have to disappear for the people to disappear."})]}),"\n",(0,o.jsx)(t.p,{children:"An experienced engineer working with AI can now finish what a whole team used to do. The product is still there, users still pay, and what disappears are the positions that would otherwise have been filled."}),"\n",(0,o.jsxs)(t.p,{children:['In "',(0,o.jsx)(t.a,{href:"/docs/notes/ai-title-game",children:"The People Who Built AI Were Laid Off, the People Who Promoted It Stayed"}),"\", I wrote about a restaurant on the third floor of a shopping mall. This time, it's another shop in the same mall."]}),"\n",(0,o.jsx)(t.h2,{id:"the-old-noodle-house-on-the-second-floor-the-machines-came-the-apprentices-left",children:"The old noodle house on the second floor: the machines came, the apprentices left"}),"\n",(0,o.jsx)(t.p,{children:"On the second floor of the mall there is an old noodle house that sells one thing: a bowl of noodle soup."}),"\n",(0,o.jsx)(t.p,{children:"It opened before the restaurant on the third floor. Later it became a chain and went public. The kitchen at the flagship had ten people: three master cooks and seven apprentices. The apprentices started by washing bowls and chopping spring onions. Only after a few years did they get to touch the stock that had been simmering for twenty years."}),"\n",(0,o.jsx)(t.p,{children:"One year, head office brought in new equipment: automatic cutters, temperature-controlled stock pots, an order system. With the machines, the three master cooks could handle what ten people used to."}),"\n",(0,o.jsx)(t.p,{children:"The noodles were the same, and customers still queued. Finance's report looked great: labour costs down, gross margin at a record high."}),"\n",(0,o.jsx)(t.p,{children:"The seven apprentice positions vanished from the next year's headcount plan. No one was laid off; the positions just weren't filled again. Nobody was fired on paper. The report simply said \"workforce structure optimised\"."}),"\n",(0,o.jsx)(t.p,{children:"Where did the money saved go?"}),"\n",(0,o.jsx)(t.p,{children:"Some of it went into new branches. The fit-out and equipment of a new branch go into the annual report. They are assets, and they make an expansion story to tell shareholders."}),"\n",(0,o.jsx)(t.p,{children:"Some of it went into share buybacks and dividends. The share price rose, and management's bonuses rose with it."}),"\n",(0,o.jsx)(t.p,{children:"None of it went into training apprentices. Training is an expense, deducted from that year's profit. An apprentice you train might be poached by the shop across the corridor three years later. Shareholders can't see the return on that investment, and management can't wait long enough for it."}),"\n",(0,o.jsx)(t.p,{children:"Ten years went by like this."}),"\n",(0,o.jsx)(t.p,{children:"The master cooks retired one by one. On the day the last one left, the company discovered that no one knew how to make the stock."}),"\n",(0,o.jsx)(t.p,{children:"The machines could control temperature and keep time. They didn't know which batch of bones needed another half hour, or that you use a little less salt when the weather turns cold. None of this had ever been written down. It was passed on only in the years an apprentice stood next to a master at the stove."}),"\n",(0,o.jsx)(t.p,{children:"And those years had been cut."}),"\n",(0,o.jsx)(t.p,{children:'The company\'s fix came quickly: buy ready-made stock packs from a central kitchen, the same kind the third-floor restaurant ended up using. The annual report read: "Introduced standardised soup base to ensure consistent quality across all branches."'}),"\n",(0,o.jsx)(t.p,{children:"The noodles are still the same bowl of noodles. It's just that, from the inside, they have slowly turned into a ready meal."}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.img,{alt:"Comic: The old noodle house \u2014 the machines came, the apprentices left",src:n(11446).A+"",width:"1280",height:"1714"})}),"\n",(0,o.jsx)(t.h2,{id:"back-in-software-terms-what-disappears-is-the-entry-point",children:"Back in software terms: what disappears is the entry point"}),"\n",(0,o.jsx)(t.p,{children:"The noodle house is a metaphor. The structure is what is happening in software right now."}),"\n",(0,o.jsx)(t.p,{children:"A software team used to look roughly like this: one architect, a few seniors, and a layer of mid-level and junior engineers. When AI arrived, the first work to be compressed was the middle and lower layers: CRUD, front-end pages, boilerplate, test scaffolding, documentation."}),"\n",(0,o.jsx)(t.p,{children:"This work used to belong to juniors, and it was also where juniors learned. In the years they spent writing it, they gradually found their way down to how the system really worked. Just as an apprentice starts with spring onions and only reaches the stock years later."}),"\n",(0,o.jsx)(t.p,{children:"Now that layer is done by senior engineers with AI. A team of ten becomes a team of three, and the product still ships. The company doesn't need to lay anyone off; it just stops opening positions. Layoffs are visible. Positions that were never opened are not, and no statistic records them."}),"\n",(0,o.jsx)(t.p,{children:"I'm an example myself. I haven't hand-written code in years, and my syntax has gone rusty, yet with AI I built my own website. Ten years ago, that workload would have meant hiring one or two front-end developers. I didn't replace anyone. The position simply never came into existence."}),"\n",(0,o.jsx)(t.p,{children:"What remains are the two ends. At one end are the people who handle the foundations: CI/CD, signing, deployment, and the legacy code nobody dares touch. At the other end are the people who work out what users actually want."}),"\n",(0,o.jsx)(t.p,{children:"The problem comes ten years from now. Today's senior engineers all climbed up through that middle layer. With the layer gone, who takes over the foundations?"}),"\n",(0,o.jsx)(t.p,{children:"The legacy code is the same. Cleaning it up brings no new revenue and no demo; on the quarterly report it is only a cost, so nobody pays for it. It's like that pot of stock: once the people who understand it retire, the only option is to replace the whole thing with a pack."}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.img,{alt:"Comic: In software terms \u2014 what disappears is the entry point",src:n(18827).A+"",width:"1400",height:"1875"})}),"\n",(0,o.jsx)(t.h2,{id:"why-money-flows-to-machines-not-people",children:"Why money flows to machines, not people"}),"\n",(0,o.jsx)(t.p,{children:"Many people say listed companies have no foresight and don't invest in the future. That's only half true. Over the past few years, tech companies have poured astronomical sums into AI capital spending, building GPUs and data centres batch after batch, all with money the market gave them."}),"\n",(0,o.jsxs)(t.p,{children:["The question isn't whether they invest. It's that the stock market chooses ",(0,o.jsx)(t.strong,{children:"which future gets the investment"}),"."]}),"\n",(0,o.jsx)(t.p,{children:"The market rewards investment that becomes an asset and can be told as a story. GPUs and data centres are capitalised in the accounts and depreciated over years, so the current quarter's earnings per share don't take the whole hit. They can also be pitched to investors: we lead in AI."}),"\n",(0,o.jsx)(t.p,{children:"The market punishes money invested in people. Hiring juniors, training, cleaning up legacy code: all of it is a current expense that lowers earnings directly, and none of it makes a story. Training is even worse: once trained, people can leave for a competitor, and the return goes to someone else."}),"\n",(0,o.jsx)(t.p,{children:"Add three mechanisms on top:"}),"\n",(0,o.jsxs)(t.ul,{children:["\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Quarterly reporting"})," turns management's unit of time into three months."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Executive tenure"})," lasts a few years, with pay tied to the share price and stock options. An investment that takes ten years to pay back will be harvested long after they've gone."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Buybacks"})," are the fastest way to return money to shareholders. They lift the share price immediately, which is safer than putting the money somewhere with no visible return."]}),"\n"]}),"\n",(0,o.jsx)(t.p,{children:"But don't put all the blame on being listed. My family's business back in the day was never listed, and it went the same way: profits on paper, cash it couldn't collect, borrowing to keep going until the end. Private equity is even more short-sighted than listed companies: buy, break up, sell, done in one cut."}),"\n",(0,o.jsxs)(t.p,{children:["The more fundamental rule is this: ",(0,o.jsx)(t.strong,{children:"if the person making the decision has a shorter time horizon than the investment's payback period, they won't make it."})," The stock market simply shortens that horizon systematically, so that short-sightedness becomes the rational choice. The management of the second-floor noodle house weren't stupid. They just couldn't wait for the day the apprentices were ready."]}),"\n",(0,o.jsx)(t.h2,{id:"the-efficiency-law-i-used-to-believe-and-where-it-breaks",children:"The efficiency law I used to believe, and where it breaks"}),"\n",(0,o.jsx)(t.p,{children:"For the past fifteen or twenty years, I worked on automation myself, and I believed in an economic law: there's no reason to hold back the progress of a whole society to protect some people's jobs. The money earned from higher efficiency can be used to look after the people who were replaced. And there's no need to feel guilty about earning more."}),"\n",(0,o.jsxs)(t.p,{children:["That law has one precondition: ",(0,o.jsx)(t.strong,{children:"the money flows back."})]}),"\n",(0,o.jsx)(t.p,{children:"This is how the internet and automation were supposed to work: save labour, produce extra value, then use that value to meet demand that hasn't been met yet. New industries appear, new jobs appear, things get cheaper, and more people can afford a car or a home. On the whole, more people should end up better off."}),"\n",(0,o.jsx)(t.p,{children:"But look at a bowl of fish ball noodles from a street stall. It hasn't got cheaper because of efficiency. If anything it costs several times what it used to, and the quality is worse. Companies earn more, and the world has printed more money, but that money hasn't turned into wages."}),"\n",(0,o.jsx)(t.p,{children:"Put it back in the second-floor noodle house, and the loop is clear:"}),"\n",(0,o.jsxs)(t.ol,{children:["\n",(0,o.jsx)(t.li,{children:"Efficiency rises, and labour costs fall."}),"\n",(0,o.jsx)(t.li,{children:"The savings become profit, and profit becomes buybacks, dividends and assets that can go on the books."}),"\n",(0,o.jsx)(t.li,{children:"Asset prices rise, and those who hold assets benefit first."}),"\n",(0,o.jsx)(t.li,{children:"Wages don't rise, prices still do, and ordinary people can spend less."}),"\n",(0,o.jsx)(t.li,{children:"With no new demand, the company cuts costs and automates again, back to step one."}),"\n"]}),"\n",(0,o.jsx)(t.p,{children:"Efficiency itself isn't the problem. What breaks is step two: the money stays in assets and doesn't flow back to create new demand. If it never reaches the people who bore the losses, what efficiency brings isn't progress. It's people turning on each other."}),"\n",(0,o.jsx)(t.h2,{id:"investing-in-the-machines-future-not-peoples",children:"Investing in the machines' future, not people's"}),"\n",(0,o.jsx)(t.p,{children:"So, back to the argument at the start: can a product be replaced by a single prompt? No. But that's the wrong question."}),"\n",(0,o.jsx)(t.p,{children:"The right question is: when the same product needs fewer people, where does the money saved go?"}),"\n",(0,o.jsx)(t.p,{children:"The answer is machines, assets and shareholders. The money does go back into investing in the future. It's just the machines' future, not people's."}),"\n",(0,o.jsx)(t.p,{children:"The second-floor noodle house won't close. It will keep opening branches, keep paying dividends, and its annual reports will keep looking good. All it loses is the stock, and a whole generation of apprentices who never got the chance to stand at the stove."}),"\n",(0,o.jsx)(t.p,{children:"Layoffs make the news. Positions that were never opened don't. What breaks isn't one job. It's a generation's way in."})]})}function p(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},18827(e,t,n){n.d(t,{A:()=>o});const o=n.p+"assets/images/apprentice-gone-entry-a62af3561ab888a83bc4e8802723dbd7.webp"},11446(e,t,n){n.d(t,{A:()=>o});const o=n.p+"assets/images/apprentice-gone-story-d12ed30c8f409e98d51aeb70cd43b9e2.webp"},28453(e,t,n){n.d(t,{R:()=>i,x:()=>r});var o=n(96540);const a={},s=o.createContext(a);function i(e){const t=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),o.createElement(s.Provider,{value:t},e.children)}}}]);